package main

import (
 "bytes"; "context"; "encoding/hex"; "encoding/json"; "fmt"; "io"; "log"; "net/http"; "os"; "path/filepath"; "strconv"; "strings"; "time"
)

type RPC struct{ URLs []string; Client *http.Client; Preferred int }
type rpcError struct{Code int `json:"code"`; Message string `json:"message"`; Data json.RawMessage `json:"data"`}
type rpcResp struct{ ID int `json:"id"`; Result json.RawMessage `json:"result"`; Error *rpcError `json:"error"` }
type rpcReq struct{ JSONRPC string `json:"jsonrpc"`; ID int `json:"id"`; Method string `json:"method"`; Params any `json:"params"` }
type Block struct{ Number,Timestamp string; Transactions []Tx `json:"transactions"` }
type Tx struct{ Hash string `json:"hash"`; To *string `json:"to"`; From,Value,Input string }
type Receipt struct{ ContractAddress *string `json:"contractAddress"`; Status,GasUsed string }

func newRPC(raw string)*RPC{var urls []string;for _,u:=range strings.FieldsFunc(raw,func(r rune)bool{return r==','||r==';'||r=='\n'}){u=strings.TrimSpace(u);if u!=""{urls=append(urls,u)}};return &RPC{URLs:urls,Client:&http.Client{Timeout:20*time.Second}}}
func retryDelay(resp *http.Response,round int)time.Duration{if resp!=nil{if s:=resp.Header.Get("Retry-After");s!=""{if n,e:=strconv.Atoi(s);e==nil&&n>0&&n<=30{return time.Duration(n)*time.Second}}};return time.Duration(1<<uint(round))*time.Second}
func (r *RPC) post(ctx context.Context,payload []byte)([]byte,error){if len(r.URLs)==0{return nil,fmt.Errorf("no RPC URLs configured")};var errs []string;start:=r.Preferred
 for round:=0;round<4;round++{var wait time.Duration;for off:=0;off<len(r.URLs);off++{idx:=(start+off)%len(r.URLs);req,e:=http.NewRequestWithContext(ctx,"POST",r.URLs[idx],bytes.NewReader(payload));if e!=nil{return nil,e};req.Header.Set("Content-Type","application/json");resp,e:=r.Client.Do(req);if e!=nil{errs=append(errs,fmt.Sprintf("rpc[%d] %v",idx,e));continue};b,_:=io.ReadAll(resp.Body);resp.Body.Close();if resp.StatusCode/100!=2{errs=append(errs,fmt.Sprintf("rpc[%d] http %d",idx,resp.StatusCode));if resp.StatusCode==429||resp.StatusCode>=500{if d:=retryDelay(resp,round);d>wait{wait=d};continue};return nil,fmt.Errorf("rpc[%d] http %d: %s",idx,resp.StatusCode,string(b))};r.Preferred=idx;return b,nil};if wait==0{wait=retryDelay(nil,round)};select{case<-ctx.Done():return nil,ctx.Err();case<-time.After(wait):}}
 return nil,fmt.Errorf("all RPC attempts failed: %s",strings.Join(errs,"; "))}
func (r *RPC) call(ctx context.Context,method string,params any,out any)error{body,_:=json.Marshal(rpcReq{"2.0",1,method,params});b,e:=r.post(ctx,body);if e!=nil{return e};var rr rpcResp;if e=json.Unmarshal(b,&rr);e!=nil{return e};if rr.Error!=nil{return fmt.Errorf("rpc %d: %s",rr.Error.Code,rr.Error.Message)};return json.Unmarshal(rr.Result,out)}
func (r *RPC) blocks(ctx context.Context,start,end uint64)([]Block,error){reqs:=make([]rpcReq,0,int(end-start+1));for n:=start;n<=end;n++{reqs=append(reqs,rpcReq{"2.0",int(n-start+1),"eth_getBlockByNumber",[]any{fmt.Sprintf("0x%x",n),true}})};body,_:=json.Marshal(reqs);b,e:=r.post(ctx,body);if e!=nil{return nil,e};var rs []rpcResp;if e=json.Unmarshal(b,&rs);e!=nil{return nil,e};byID:=make(map[int]rpcResp,len(rs));for _,x:=range rs{byID[x.ID]=x};out:=make([]Block,0,len(reqs));for i:=1;i<=len(reqs);i++{rr,ok:=byID[i];if !ok{return nil,fmt.Errorf("batch response missing id %d",i)};if rr.Error!=nil{return nil,fmt.Errorf("batch id %d rpc %d: %s",i,rr.Error.Code,rr.Error.Message)};var bl Block;if e=json.Unmarshal(rr.Result,&bl);e!=nil{return nil,fmt.Errorf("batch id %d decode: %w",i,e)};if bl.Number==""{return nil,fmt.Errorf("batch id %d returned empty block",i)};out=append(out,bl)};return out,nil}
func hexUint(s string)(uint64,error){return strconv.ParseUint(strings.TrimPrefix(s,"0x"),16,64)}
func envInt(k string,d int)int{v,_:=strconv.Atoi(os.Getenv(k));if v<=0{return d};return v}
func newBig(b []byte)uint64{var n uint64;start:=0;if len(b)>8{start=len(b)-8};for _,x:=range b[start:]{n=n<<8|uint64(x)};return n}
func decodeABIString(raw string)string{b,e:=hex.DecodeString(strings.TrimPrefix(raw,"0x"));if e!=nil||len(b)==0{return ""};if len(b)>=64{n:=int(newBig(b[32:64]));if n>0&&64+n<=len(b){return strings.TrimSpace(string(b[64:64+n]))}};if len(b)>=32{return strings.TrimSpace(strings.TrimRight(string(b[:32]),"\x00"))};return ""}
func ethCall(ctx context.Context,r *RPC,a,s string)string{var out string;if r.call(ctx,"eth_call",[]any{map[string]string{"to":a,"data":s},"latest"},&out)!=nil{return ""};return out}
func tokenMeta(ctx context.Context,r *RPC,a string)(string,string,string,string){return decodeABIString(ethCall(ctx,r,a,"0x06fdde03")),decodeABIString(ethCall(ctx,r,a,"0x95d89b41")),hexNum(ethCall(ctx,r,a,"0x313ce567")),hexNum(ethCall(ctx,r,a,"0x18160ddd"))}
func hexNum(s string)string{if s==""||s=="0x"{return "-"};n,e:=hexUint(s);if e!=nil{return "-"};return strconv.FormatUint(n,10)}
func telegram(ctx context.Context,t,c,text string)error{if t==""||c==""{return fmt.Errorf("telegram secrets missing")};u:="https://api.telegram.org/bot"+t+"/sendMessage";p,_:=json.Marshal(map[string]any{"chat_id":c,"text":text,"disable_web_page_preview":true});req,_:=http.NewRequestWithContext(ctx,"POST",u,bytes.NewReader(p));req.Header.Set("Content-Type","application/json");resp,e:=http.DefaultClient.Do(req);if e!=nil{return e};defer resp.Body.Close();if resp.StatusCode/100!=2{b,_:=io.ReadAll(resp.Body);return fmt.Errorf("telegram %d: %s",resp.StatusCode,string(b))};return nil}
func empty(s,d string)string{if strings.TrimSpace(s)==""{return d};return s}
func shortSupply(raw,dec string)string{if raw=="-"||dec=="-"{return raw};d,e:=strconv.Atoi(dec);if e!=nil||d>18{return raw};n,e:=strconv.ParseUint(raw,10,64);if e!=nil{return raw};x:=float64(n);for i:=0;i<d;i++{x/=10};return fmt.Sprintf("%.4g",x)}
func loadCursor(path string)(uint64,bool){b,e:=os.ReadFile(path);if e!=nil{return 0,false};n,e:=strconv.ParseUint(strings.TrimSpace(string(b)),10,64);return n,e==nil}
func saveCursor(path string,n uint64)error{if e:=os.MkdirAll(filepath.Dir(path),0755);e!=nil{return e};tmp:=path+".tmp";if e:=os.WriteFile(tmp,[]byte(strconv.FormatUint(n,10)+"\n"),0644);e!=nil{return e};return os.Rename(tmp,path)}

func main(){rpcRaw:=os.Getenv("ARC_RPC_URLS");if rpcRaw==""{rpcRaw=os.Getenv("ARC_RPC_URL")};if rpcRaw==""{log.Fatal("ARC_RPC_URL or ARC_RPC_URLS is required")};token,chat:=os.Getenv("TELEGRAM_BOT_TOKEN"),os.Getenv("TELEGRAM_CHAT_ID");initial,maxBlocks,maxAlerts,batchSize:=envInt("INITIAL_LOOKBACK_BLOCKS",240),envInt("MAX_BLOCKS_PER_RUN",600),envInt("MAX_ALERTS",20),envInt("BLOCK_BATCH_SIZE",40);if batchSize>50{batchSize=50};stateFile:=os.Getenv("STATE_FILE");if stateFile==""{stateFile=".state/cursor"};ctx,cancel:=context.WithTimeout(context.Background(),7*time.Minute);defer cancel();r:=newRPC(rpcRaw);if os.Getenv("TEST_ALERT")=="1"{if e:=telegram(ctx,token,chat,"✅ Arc Mainnet Monitor 测试成功");e!=nil{log.Fatal(e)};return};var chain string;if e:=r.call(ctx,"eth_chainId",[]any{},&chain);e!=nil{log.Fatal(e)};if strings.ToLower(chain)!="0x13b2"{log.Fatalf("wrong chain id %s, expected 0x13b2 (5042)",chain)};var lh string;if e:=r.call(ctx,"eth_blockNumber",[]any{},&lh);e!=nil{log.Fatal(e)};latest,e:=hexUint(lh);if e!=nil{log.Fatal(e)}
 start:=uint64(0);if cursor,ok:=loadCursor(stateFile);ok{if cursor>=latest{log.Printf("up to date cursor=%d latest=%d",cursor,latest);return};start=cursor+1;log.Printf("resume cursor=%d start=%d latest=%d",cursor,start,latest)}else if latest>uint64(initial){start=latest-uint64(initial)+1;log.Printf("no cursor; bootstrap last %d blocks start=%d latest=%d",initial,start,latest)};end:=latest;if maxBlocks>0&&end-start+1>uint64(maxBlocks){end=start+uint64(maxBlocks)-1};found:=0
 for bs:=start;bs<=end;{be:=bs+uint64(batchSize)-1;if be>end{be=end};blocks,e:=r.blocks(ctx,bs,be);if e!=nil{log.Fatalf("block batch %d-%d unreadable; cursor NOT advanced: %v",bs,be,e)};for _,b:=range blocks{n,e:=hexUint(b.Number);if e!=nil{log.Fatalf("invalid block number %q; cursor NOT advanced",b.Number)};ts,_:=hexUint(b.Timestamp);for _,tx:=range b.Transactions{if tx.To!=nil{continue};var rc Receipt;if e:=r.call(ctx,"eth_getTransactionReceipt",[]any{tx.Hash},&rc);e!=nil{log.Fatalf("receipt %s unreadable; cursor NOT advanced: %v",tx.Hash,e)};if rc.ContractAddress==nil||*rc.ContractAddress==""||rc.Status=="0x0"{continue};addr:=*rc.ContractAddress;name,symbol,dec,supplyRaw:=tokenMeta(ctx,r,addr);kind:="Contract";if name!=""||symbol!=""||dec!="-"{kind="ERC20-like Token"};var code string;_=r.call(ctx,"eth_getCode",[]any{addr,"latest"},&code);codeBytes:=len(strings.TrimPrefix(code,"0x"))/2;gas:=hexNum(rc.GasUsed);age:="-";if ts>0{age=time.Since(time.Unix(int64(ts),0)).Round(time.Second).String()};if found<maxAlerts{msg:=fmt.Sprintf("🚨 ARC NEW %s\n\n🏷 Name: %s\n🔤 Symbol: %s\n🔢 Decimals: %s\n🪙 Total Supply: %s\n\n📦 Block: %d\n⏱ Age: %s\n📄 Contract: %s\n👤 Deployer: %s\n⛽ Deploy Gas: %s\n💾 Code Size: %d bytes\n\n🔎 Contract: https://arc-scan.org/address/%s\n🔎 Tx: https://arc-scan.org/tx/%s\n\n⚠️ 新部署仅代表链上活动；未验证流动性、持仓集中度、交易权限或安全性。",kind,empty(name,"-"),empty(symbol,"-"),dec,shortSupply(supplyRaw,dec),n,age,addr,tx.From,gas,codeBytes,addr,tx.Hash);if e:=telegram(ctx,token,chat,msg);e!=nil{log.Fatalf("telegram failed; cursor NOT advanced: %v",e)};found++}else{log.Printf("alert cap reached; contract %s at block %d recorded without Telegram",addr,n)}}};bs=be+1}
 if e:=saveCursor(stateFile,end);e!=nil{log.Fatal(e)};log.Printf("done chain=5042 rpc_endpoints=%d batch_size=%d start=%d end=%d latest=%d alerts=%d cursor_saved=%d",len(r.URLs),batchSize,start,end,latest,found,end)
}
